package com.bank.secondlargest;

import java.util.*;
import java.util.logging.*;

public class SecondLargestDemo {
    private static final Logger log = Logger.getLogger("SecondLargest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> amounts = List.of(5000, 20000, 20000, 15000, 8000);
        SecondLargestService service = new SecondLargestService();

        log.info(() -> "Second largest distinct: "
            + service.secondLargest(amounts).orElse(-1));   // 15000 (20000 is largest)
    }
}

// ─── Would be in service/SecondLargestService.java ───
class SecondLargestService {
    Optional<Integer> secondLargest(List<Integer> nums) {
        return nums.stream()
            .distinct()                                 // dedupe → distinct values
            .sorted(Comparator.reverseOrder())           // descending
            .skip(1)                                     // drop the largest
            .findFirst();                                // → second-largest
    }
}
